select o.status, case when o.status in ('SHIPPED', 'RETURNED') then 'priority' else 'other' end as status_group, sort_array(collect_set(p.status)) as status_list, max(p.paid_at) as latest_paid_at from payments p left join orders o on p.order_id = o.id inner join stores s on o.store_id = s.id where s.region in ('East', 'West', 'Central') group by o.status, case when o.status in ('SHIPPED', 'RETURNED') then 'priority' else 'other' end order by latest_paid_at;
